        "基礎資料を確認する::登記事項証明書、公図、地積測量図、建物図面、管理規約、固定資産税資料、賃貸借契約を確認します。所有者、面積、地目、抵当権、私道負担、敷地権など、権利と物件の基本を押さえます。",
        "現地を確認する::境界標、越境、接道、擁壁、インフラ引込、建物劣化、雨漏り、周辺環境、嫌悪施設、利用状況を見ます。写真は単なる記録ではなく、確認日時と紐づけて後から説明できるようにします。",
        "役所で調べる::用途地域、建ぺい率、容積率、防火地域、道路種別、都市計画、開発許可、建築確認、ハザード情報、上下水道などを確認します。自治体ごとに確認部署や資料の出方が違うため、調査メモを残します。",
