        "実務の勘所::物件調査では、登記、現地、役所、売主ヒアリングを別々に集めるだけでは不十分です。法務省の不動産登記の説明にもあるように、購入前には現地確認に加え、登記事項証明書などで面積、所有者、差押え、抵当権の有無を調べることが重要です。登記の事実と現況が一致しているかを確認する視点が欠かせません。",
        "データと根拠の残し方::現地では、境界標、越境、接道、私道、擁壁、排水、インフラ、建物劣化、近隣環境を確認します。役所では、用途地域、建ぺい率、容積率、道路種別、防火地域、都市計画、開発許可、建築確認、ハザード情報を確認します。調査結果は、事実、判断、未確認事項に分けて記録します。",
        "不動産テックの使いどころ::不動産情報ライブラリや地図系サービスは、価格情報、都市計画、防災、周辺施設を初期確認する入口になります。ただし、自治体資料、道路台帳、上下水道、建築指導課での確認は地域差が大きいため、画面キャプチャだけでなく確認部署、確認日、担当者メモを残します。",
        "よくある詰まりどころ::よくある詰まりは、資料間の差分を見つけても誰に確認するか決めていないことです。登記面積と実測面積、建築確認と現況用途、道路扱い、越境、未登記部分は、売主、土地家屋調査士、建築士、弁護士、自治体へ確認が必要になることがあります。論点表を作り、重説と契約条件に反映します。",
