        "データと根拠の残し方::実務では、説明前の書面提供、相手方の承諾、本人確認、宅建士証の提示、通信環境、画面共有、質疑応答、説明後の記録を案件ごとに残します。電子契約サービスを使う場合も、署名権限、代理人、社内承認、添付書類、保管先を確認しないと、後で証跡が不足します。",
        "不動産テックの使いどころ::電子化の効果は、移動時間削減だけではありません。説明資料、調査根拠、質疑回答、修正履歴を同じ案件フォルダに置くことで、重説の品質管理がしやすくなります。一方で、録画や本人確認資料を扱う場合は、個人情報管理、保存期間、閲覧権限を社内規程に合わせる必要があります。",
