        "よくある詰まりどころ::失敗しやすいのは、案件数だけをKPIにすることです。取得方針に合わない案件を増やしても、検討工数が膨らむだけです。初期スクリーニングで重大な除外理由を早く見つけ、見送った理由を分類することで、次の探索条件を改善できます。",
