        "実務の勘所::販売資料作成では、訴求と正確性を両立させます。投資家向けならNOI、利回り、賃貸借契約、修繕履歴を厚めにし、デベロッパー向けなら用途地域、容積、接道、開発余地を重視します。事業会社向けなら、立地、動線、利用条件、周辺環境が検討しやすい形にします。",
        "データと根拠の残し方::広告や販売図面では、不動産公正取引協議会の表示規約や宅建業法上の表示事項に注意します。根拠のない最上級表現、徒歩分数、面積、価格、取引態様、広告開始時期、未確定情報の扱いは確認が必要です。業者間資料であっても、外部に出る前提で表現を整えます。",
