        "よくある詰まりどころ::よくある失敗は、一度作った資料を販売期間中に更新しないことです。価格変更、空室状況、賃料改定、内覧条件、特記事項が変わったら、版数と更新日を残します。古い資料を受け取った買主が後で認識違いを起こさないよう、配布先も管理します。",
