        "意思決定者を把握する::相談者本人だけで決められるのか、家族、共有者、法人役員、投資委員会、金融機関が関わるのかを確認します。意思決定者が見えていないと、後工程で承認が止まりやすくなります。",
        "次回提案へ落とす::ヒアリング結果をもとに、査定、候補物件、売却方針、買付条件、必要資料リストへ落とします。初回面談のメモを案件データとして残すと、担当変更や分業でも提案品質を保ちやすくなります。",
